import random
import time

import pytest

import cachetools
from cachetools.func import (
    fifo_cache,
    lfu_cache,
    lru_cache,
    rr_cache,
    ttl_cache,
    _UnboundTTLCache,
)


class Counter:
    def __init__(self):
        self.calls = 0

    def __call__(self, *args, **kwargs):
        self.calls += 1
        return args, kwargs


@pytest.mark.parametrize(
    "decorator",
    [fifo_cache, lfu_cache, lru_cache, rr_cache, ttl_cache],
)
def test_default_maxsize(decorator):
    @decorator()
    def func(x):
        return x * 2

    assert func.cache_parameters() == {"maxsize": 128, "typed": False}
    assert func(3) == 6
    assert func(3) == 6


@pytest.mark.parametrize(
    "decorator",
    [fifo_cache, lfu_cache, lru_cache, rr_cache, ttl_cache],
)
def test_explicit_maxsize(decorator):
    @decorator(maxsize=5)
    def func(x):
        return x

    assert func.cache_parameters() == {"maxsize": 5, "typed": False}
    for i in range(10):
        assert func(i) == i


@pytest.mark.parametrize(
    "decorator",
    [fifo_cache, lfu_cache, lru_cache, rr_cache, ttl_cache],
)
def test_typed_flag(decorator):
    @decorator(typed=True)
    def func(x):
        return x

    assert func.cache_parameters() == {"maxsize": 128, "typed": True}
    # typed keys distinguish 1 and 1.0
    assert func(1) == 1
    assert func(1.0) == 1.0


def test_typed_parameters():
    @lru_cache(maxsize=10, typed=True)
    def func(x):
        return x

    assert func.cache_parameters() == {"maxsize": 10, "typed": True}


@pytest.mark.parametrize(
    "decorator",
    [fifo_cache, lfu_cache, lru_cache, rr_cache, ttl_cache],
)
def test_unbound_maxsize_none(decorator):
    @decorator(maxsize=None)
    def func(x):
        return x * 3

    assert func.cache_parameters() == {"maxsize": None, "typed": False}
    values = list(range(200))
    results = [func(v) for v in values]
    assert results == [v * 3 for v in values]
    # unbounded should keep all keys cached
    cached_results = [func(v) for v in values]
    assert cached_results == results


@pytest.mark.parametrize(
    "decorator",
    [fifo_cache, lfu_cache, lru_cache, rr_cache, ttl_cache],
)
def test_callable_maxsize_as_decorator(decorator):
    calls = Counter()

    @decorator
    def func(x):
        calls.calls += 1
        return x + 1

    assert func.cache_parameters() == {"maxsize": 128, "typed": False}
    assert func(1) == 2
    assert func(1) == 2
    assert calls.calls == 1


@pytest.mark.parametrize(
    "decorator",
    [fifo_cache, lfu_cache, lru_cache, rr_cache, ttl_cache],
)
def test_direct_decorator_with_args(decorator):
    calls = Counter()

    @decorator()
    def func(a, b):
        calls.calls += 1
        return a + b

    assert func(1, 2) == 3
    assert func(1, 2) == 3
    assert func(2, 1) == 3
    assert calls.calls == 2


@pytest.mark.parametrize(
    "decorator",
    [fifo_cache, lfu_cache, lru_cache, rr_cache, ttl_cache],
)
def test_cache_info_hits_misses(decorator):
    @decorator(maxsize=4)
    def func(x):
        return x

    assert func(1) == 1
    assert func(1) == 1
    info = func.cache_info()
    assert info.hits == 1
    assert info.misses == 1
    assert info.maxsize == 4


@pytest.mark.parametrize(
    "decorator",
    [fifo_cache, lfu_cache, lru_cache, rr_cache, ttl_cache],
)
def test_cache_info_unbound(decorator):
    @decorator(maxsize=None)
    def func(x):
        return x

    func(1)
    func(1)
    info = func.cache_info()
    assert info.hits == 1
    assert info.misses == 1
    assert info.maxsize is None


@pytest.mark.parametrize(
    "decorator",
    [fifo_cache, lfu_cache, lru_cache, rr_cache, ttl_cache],
)
def test_cache_clear(decorator):
    @decorator(maxsize=4)
    def func(x):
        return x

    func(1)
    assert func.cache_info().currsize == 1
    func.cache_clear()
    assert func.cache_info().currsize == 0
    # recompute after clear
    func(1)
    assert func.cache_info().currsize == 1
    assert func.cache_info().misses == 2


def test_fifo_eviction_order():
    @fifo_cache(maxsize=2)
    def func(x):
        return x

    func(1)
    func(2)
    # accessing 1 should not affect FIFO order
    func(1)
    func(3)  # evicts 1 (first in)
    assert func.cache_info().currsize == 2
    # 1 was evicted:
    misses_before = func.cache_info().misses
    func(1)
    assert func.cache_info().misses == misses_before + 1
    # 2 should still be cached
    misses_now = func.cache_info().misses
    func(2)
    assert func.cache_info().misses == misses_now


def test_lru_eviction_order():
    @lru_cache(maxsize=2)
    def func(x):
        return x

    func(1)
    func(2)
    func(1)  # touch 1 -> 2 is LRU
    func(3)  # evicts 2
    misses = func.cache_info().misses
    func(2)  # miss
    assert func.cache_info().misses == misses + 1
    misses = func.cache_info().misses
    func(1)  # hit
    assert func.cache_info().misses == misses


def test_lfu_eviction_order():
    @lfu_cache(maxsize=2)
    def func(x):
        return x

    func(1)
    func(2)
    func(1)  # 1 used twice, 2 used once
    func(3)  # evicts 2
    misses = func.cache_info().misses
    func(2)
    assert func.cache_info().misses == misses + 1
    misses = func.cache_info().misses
    func(1)
    assert func.cache_info().misses == misses


def test_rr_choice_used():
    chosen = []

