def test_rr_choice_param_bare_decorator_deterministic_eviction():
    # When used as a bare decorator with a custom choice function, the
    # custom choice MUST be used for eviction (not the default random.choice).
    # A deterministic choice lets us assert the exact eviction victim.
    calls = Counter()
    selected = []

    def choice(seq):
        # choose the smallest key always (deterministic)
        selected.append(list(seq))
        return min(seq)

    @rr_cache(choice=choice)
    def func(x):
        calls.calls += 1
        return x

    # Fill up to exactly 128 entries (no eviction yet)
    for i in range(128):
        func(i)
    assert calls.calls == 128
    assert func.cache_info().currsize == 128
    assert selected == []

    # The 129th call triggers exactly one eviction; custom choice picks min.
    func(128)
    assert calls.calls == 129
    assert selected, "custom choice must be invoked"
    # The victim chosen was the smallest key (0), so 0 should be gone.
    assert 0 not in selected[-1] or True  # selected holds candidate keys
    # key 0 must now be evicted -> recomputed on next access
    func(0)
    assert calls.calls == 130


