@pytest.mark.parametrize(
    "decorator",
    [fifo_cache, lfu_cache, lru_cache, rr_cache, ttl_cache],
)
def test_condition_object_is_used_for_stampede_prevention(decorator):
    # The wrapper must be given a real threading.Condition so that concurrent
    # callers of the same uncached key do not stampede. We assert this by
    # having a slow function: if no condition (or barrier) is used, the
    # function would be called multiple times concurrently.
    call_count = [0]
    started = threading.Event()
    release = threading.Event()
    lock = threading.Lock()

    @decorator(maxsize=8)
    def func(x):
        with lock:
            call_count[0] += 1
        started.set()
        release.wait(timeout=2.0)
        return x * 2

    results = []

    def worker():
        results.append(func(5))

    t = threading.Thread(target=worker)
    t.start()
    # wait until the first call has started computing
    assert started.wait(timeout=2.0)
    # While the first computation is in progress, a second caller with the
    # same key must block on the condition and then reuse the cached value.
    t2 = threading.Thread(target=worker)
    t2.start()
    # give the second thread a moment to reach the wrapper
    time.sleep(0.05)
    release.set()
    t.join(timeout=2.0)
    t2.join(timeout=2.0)
    assert results == [10, 10]
    # The condition ensures only a single underlying computation happens.
    assert call_count[0] == 1


