    assert func(2) == 3
    assert func(1) == 2
    assert func(2) == 3
    assert calls.calls == 2


def test_rr_bare_decorator_default_choice_is_random_choice():
    # For the bare-decorator path (maxsize is callable), the default choice
    # function must be random.choice. Verify by checking that the cache's
    # choice property is random.choice. We can exercise it through eviction.
    cache_holder = {}

    original_rrcache = cachetools.RRCache

    class RecordingRRCache(original_rrcache):
        def __init__(self, maxsize, choice=random.choice, getsizeof=None):
            super().__init__(maxsize, choice, getsizeof)
            cache_holder["cache"] = self

    try:
        cachetools.func.RRCache = RecordingRRCache  # type: ignore
        # Patch the name resolved inside cachetools.func
        import cachetools.func as func_mod

        saved = func_mod.RRCache
        func_mod.RRCache = RecordingRRCache
        try:
            @rr_cache
            def func(x):
                return x
        finally:
            func_mod.RRCache = saved
    finally:
        cachetools.func.RRCache = original_rrcache  # type: ignore

    cache = cache_holder["cache"]
    assert cache.choice is random.choice


def test_rr_bare_decorator_custom_choice_reaches_cache():
    # When rr_cache is used as a bare decorator with a custom choice, that
    # choice must be forwarded to the inner RRCache. If the choice argument
    # were dropped, RRCache would fall back to random.choice.
    selected = []

    def choice(seq):
        selected.append(list(seq))
        return seq[0]

    @rr_cache(choice=choice)
    def func(x):
        return x

    # Fill to just below capacity: no eviction, choice must not be called.
    for i in range(128):
        func(i)
    assert selected == []
    # Trigger exactly one eviction: choice must be called with the candidates.
    func(128)
    assert len(selected) == 1
    assert set(selected[0]) == set(range(128))
    # The chosen victim (min key = 0) must have been evicted, so recompute.
    calls_before = func.cache_info().misses
    func(0)
    assert func.cache_info().misses == calls_before + 1


def test_ttl_bare_decorator_custom_timer_reaches_cache():
    # When ttl_cache is used as a bare decorator with a custom timer, the
    # timer must be forwarded to the inner TTLCache. A distinctive timer
    # offset makes a default (monotonic) timer evident by wrong expiry.
    timer_value = [0.0]

    def timer():
        return timer_value[0]

    calls = Counter()

    @ttl_cache(ttl=7, timer=timer)
    def func(x):
        calls.calls += 1
        return x

    func(1)
    assert calls.calls == 1
    # Move fake timer to just before expiry: must still hit.
    timer_value[0] = 6.9
    func(1)
    assert calls.calls == 1
    # Move to expiry: must miss and recompute.
    timer_value[0] = 7.0
    func(1)
    assert calls.calls == 2


def test_ttl_bare_decorator_ttl_value_used():
    # Use a very large ttl and a custom timer to distinguish from any other
    # timer wiring; item must remain valid for a long fake-time span.
    timer_value = [0.0]

    def timer():
        return timer_value[0]

    calls = Counter()

    @ttl_cache(ttl=1000, timer=timer)
    def func(x):
        calls.calls += 1
        return x

    func(1)
    assert calls.calls == 1
    # At fake time 999 the item is still valid even though many real seconds
    # worth of wall-clock would have expired a default 600 ttl; this proves
    # the custom ttl of 1000 is in effect.
    timer_value[0] = 999
    func(1)
    assert calls.calls == 1
    timer_value[0] = 1000
    func(1)
    assert calls.calls == 2
